	// items are in the queue, this method will pause until items are added to the
	// queue or the provided timeout is reached. A non-positive timeout will block
	// until items are added. If a timeout occurs, ErrTimeout is returned.
	Poll(number int64, timeout time.Duration) ([]interface{}, error)

	// Peek returns the first item in the queue by value without modifying the queue.
	Peek() (interface{}, error)

	// Empty returns a bool indicating if this queue is empty.
	Empty() bool

	// Len returns the number of items in this queue.
	Len() int64

	// Disposed returns a bool indicating if this queue has had disposed called on it.
	Disposed() bool

	// Dispose will dispose of this queue and returns the items disposed.
	// Any subsequent calls to Get or Put will return an error.
	Dispose() []interface{}
}

// PriorityItem is an item that can be added to a priority queue.
type PriorityItem interface {
	// Compare returns an int that can be used to determine ordering in the
	// priority queue. Returning 1 indicates this object is greater than the
	// other item, 0 indicates equality, and -1 indicates less than other.
	Compare(other PriorityItem) int
}
